sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }
	// 1. 获取原始4个字段的显示值
    var startDate = g_form.getValue('leave_start_date') || '';
    var startTime = g_form.getValue('leave_start_time') || '';
    var endDate = g_form.getValue('leave_end_date') || '';
    var endTime = g_form.getValue('leave_end_time') || '';

    // 2. 拼接开始时段 + 结束时段
    var startFull = startDate + ' ' + startTime;
    var endFull = endDate + ' ' + endTime;

    // 3. 赋值到展示字段（实时更新）
    g_form.setValue('leave_start_period', startFull.trim());
    g_form.setValue('leave_end_period', endFull.trim());
   //Type appropriate comment here, and begin script below

}
